create or replace function public.rental_set_financial_period_status(p_tenancy uuid,p_start date,p_end date,p_status text,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare t public.rental_tenancies%rowtype; rid uuid; begin if auth.uid() is null or p_status not in ('closed','reopened') or p_start is null or p_end is null or p_end<p_start or length(btrim(coalesce(p_reason,'')))=0 then raise exception 'A valid period, status and reason are required'; end if; select * into t from public.rental_tenancies where id=p_tenancy for update; if not found or not public.rental_financial_manager_authorized(t.organisation_id) then raise exception 'Manager approval is required'; end if; insert into public.rental_financial_closed_periods(organisation_id,tenancy_id,period_start,period_end,status,reason,closed_by) values(t.organisation_id,t.id,p_start,p_end,p_status,btrim(p_reason),auth.uid()) on conflict(tenancy_id,period_start,period_end) do update set status=excluded.status,reason=excluded.reason,closed_by=excluded.closed_by,closed_at=now() returning id into rid; return jsonb_build_object('period_id',rid,'status',p_status); end$$; revoke execute on function public.rental_set_financial_period_status(uuid,date,date,text,text) from public,anon; grant execute on function public.rental_set_financial_period_status(uuid,date,date,text,text) to authenticated;;
